<?php

use Illuminate\Contracts\Console\Kernel;
use Illuminate\Support\Facades\DB;

// Undo only the file_path generated by the read-only UI smoke test.
require dirname(__DIR__).'/vendor/autoload.php';
$app = require dirname(__DIR__).'/bootstrap/app.php';
$app->make(Kernel::class)->bootstrap();
$data = json_decode(file_get_contents(storage_path('app/private/migration/legacy-snapshot.json')), true, 512, JSON_THROW_ON_ERROR);
foreach ($data['tables']['payslips'] as $row) {
    $current = DB::table('payslips')->where('id', $row['id'])->value('file_path');
    if ($current !== $row['file_path'] && preg_match('#^/pdf_slips/Payslip_.*_[a-f0-9]{24}\.pdf$#', $current ?? '')) {
        DB::table('payslips')->where('id', $row['id'])->where('file_path', $current)->update(['file_path' => $row['file_path']]);
    }
}
echo 'Smoke-test PDF reference restored; original files retained.'.PHP_EOL;
